insert into public.challenges (slug,title,category,kind,difficulty,minutes,xp,summary,objective,instructions,steps,reference_slugs,tags) values ('uma-luz-so','Uma luz só','fotografia','diario','iniciante',30,60,'Faça um retrato usando apenas uma fonte de luz — janela, abajur ou celular.','Entender como direção e distância da luz moldam volume e emoção.',array['Escolha uma única fonte de luz e apague todas as outras.','Fotografe o mesmo rosto (ou objeto) com a luz a 45°, 90° e por trás.','Afaste e aproxime a luz: observe a sombra ficar dura ou suave.','Escolha a melhor foto e escreva em uma frase qual emoção ela transmite.']::text[],null,array['luz-de-janela','retrato-cor-unica']::text[],array['luz','retrato']::text[]) on conflict (slug) do update set title=excluded.title, category=excluded.category, kind=excluded.kind, difficulty=excluded.difficulty, minutes=excluded.minutes, xp=excluded.xp, summary=excluded.summary, objective=excluded.objective, instructions=excluded.instructions, steps=excluded.steps, reference_slugs=excluded.reference_slugs, tags=excluded.tags;
insert into public.challenges (slug,title,category,kind,difficulty,minutes,xp,summary,objective,instructions,steps,reference_slugs,tags) values ('sombra-protagonista','A sombra é a protagonista','fotografia','diario','intermediario',40,80,'Crie 3 fotos em que a sombra conta a história, não o objeto.','Treinar o olhar para formas gráficas e contraste.',array['Saia entre 11h e 14h (ou use uma lanterna em casa).','Procure sombras de grades, plantas, escadas ou pessoas.','Enquadre de forma que o objeto real fique fora ou quase fora do quadro.','Edite em preto e branco com contraste alto.']::text[],null,array['sombras-urbanas','espaco-negativo']::text[],array['contraste','rua']::text[]) on conflict (slug) do update set title=excluded.title, category=excluded.category, kind=excluded.kind, difficulty=excluded.difficulty, minutes=excluded.minutes, xp=excluded.xp, summary=excluded.summary, objective=excluded.objective, instructions=excluded.instructions, steps=excluded.steps, reference_slugs=excluded.reference_slugs, tags=excluded.tags;
insert into public.challenges (slug,title,category,kind,difficulty,minutes,xp,summary,objective,instructions,steps,reference_slugs,tags) values ('dez-fotos-um-metro','10 fotos em 1 metro quadrado','fotografia','diario','iniciante',25,50,'Fique parado em um único lugar e produza 10 fotos diferentes.','Descobrir que criatividade nasce da limitação, não do cenário.',array['Escolha um ponto e não saia dele.','Varie altura, ângulo, foco, distância e enquadramento.','Inclua ao menos uma foto abstrata e uma de detalhe.','Monte uma grade 2×5 com as 10 imagens.']::text[],null,array['geometria-de-rua','ritmo-repeticao']::text[],array['limitação','olhar']::text[]) on conflict (slug) do update set title=excluded.title, category=excluded.category, kind=excluded.kind, difficulty=excluded.difficulty, minutes=excluded.minutes, xp=excluded.xp, summary=excluded.summary, objective=excluded.objective, instructions=excluded.instructions, steps=excluded.steps, reference_slugs=excluded.reference_slugs, tags=excluded.tags;
insert into public.challenges (slug,title,category,kind,difficulty,minutes,xp,summary,objective,instructions,steps,reference_slugs,tags) values ('cartaz-tres-elementos','Cartaz com 3 elementos','design','diario','intermediario',45,90,'Crie um cartaz para um evento fictício usando só uma forma, uma palavra e uma cor.','Praticar hierarquia e síntese visual.',array['Invente um evento (ex.: festival de chuva).','Escolha UMA forma geométrica, UMA palavra e UMA cor além de preto/branco.','Explore escala: faça três versões mudando apenas o tamanho dos elementos.','Escolha a versão mais forte e justifique a escolha.']::text[],null,array['cartaz-suico','cartaz-tipografico-brutal']::text[],array['cartaz','síntese']::text[]) on conflict (slug) do update set title=excluded.title, category=excluded.category, kind=excluded.kind, difficulty=excluded.difficulty, minutes=excluded.minutes, xp=excluded.xp, summary=excluded.summary, objective=excluded.objective, instructions=excluded.instructions, steps=excluded.steps, reference_slugs=excluded.reference_slugs, tags=excluded.tags;
insert into public.challenges (slug,title,category,kind,difficulty,minutes,xp,summary,objective,instructions,steps,reference_slugs,tags) values ('logo-em-15-minutos','Logo em 15 minutos','design','diario','iniciante',15,40,'Desenhe 12 rascunhos de logo para uma marca inventada — rápido, sem apagar.','Separar geração de ideias de julgamento.',array['Sorteie um nome: ''Brisa'', ''Ferro Doce'' ou ''Coletivo Raiz''.','Em papel, faça 12 miniaturas em 15 minutos — sem borracha.','Circule as 2 melhores e anote por quê.']::text[],null,array['identidade-modular','marca-cafe-lento']::text[],array['branding','rascunho']::text[]) on conflict (slug) do update set title=excluded.title, category=excluded.category, kind=excluded.kind, difficulty=excluded.difficulty, minutes=excluded.minutes, xp=excluded.xp, summary=excluded.summary, objective=excluded.objective, instructions=excluded.instructions, steps=excluded.steps, reference_slugs=excluded.reference_slugs, tags=excluded.tags;
insert into public.challenges (slug,title,category,kind,difficulty,minutes,xp,summary,objective,instructions,steps,reference_slugs,tags) values ('redesenhe-o-cotidiano','Redesenhe o cotidiano','design','diario','avancado',60,120,'Escolha uma embalagem da sua casa e redesenhe para um público oposto.','Exercitar pensamento de público-alvo e reposicionamento.',array['Escolha uma embalagem comum (sabonete, café, biscoito).','Defina um público oposto ao original (ex.: de infantil para premium).','Mude cor, tipografia, linguagem e hierarquia.','Apresente antes/depois lado a lado.']::text[],null,array['marca-cafe-lento','paleta-terra-quente']::text[],array['embalagem','público']::text[]) on conflict (slug) do update set title=excluded.title, category=excluded.category, kind=excluded.kind, difficulty=excluded.difficulty, minutes=excluded.minutes, xp=excluded.xp, summary=excluded.summary, objective=excluded.objective, instructions=excluded.instructions, steps=excluded.steps, reference_slugs=excluded.reference_slugs, tags=excluded.tags;
insert into public.challenges (slug,title,category,kind,difficulty,minutes,xp,summary,objective,instructions,steps,reference_slugs,tags) values ('historia-em-seis-planos','Uma história em 6 planos','video','diario','intermediario',50,100,'Conte uma micro-história com exatamente 6 planos e nenhum diálogo.','Dominar começo, meio e fim apenas com imagem e corte.',array['Escreva a história em uma frase (ex.: ''alguém espera uma mensagem'').','Planeje: geral, médio, detalhe, reação, detalhe, desfecho.','Grave com o celular na horizontal, cada plano de 2 a 4 segundos.','Edite cortando no movimento e escolha uma trilha que mude o sentido.']::text[],null,array['regra-dos-tercos-quebrada','campanha-pergunta']::text[],array['narrativa','montagem']::text[]) on conflict (slug) do update set title=excluded.title, category=excluded.category, kind=excluded.kind, difficulty=excluded.difficulty, minutes=excluded.minutes, xp=excluded.xp, summary=excluded.summary, objective=excluded.objective, instructions=excluded.instructions, steps=excluded.steps, reference_slugs=excluded.reference_slugs, tags=excluded.tags;
insert into public.challenges (slug,title,category,kind,difficulty,minutes,xp,summary,objective,instructions,steps,reference_slugs,tags) values ('corte-no-ritmo','Corte no ritmo','video','diario','iniciante',30,60,'Edite 15 segundos de imagens cotidianas sincronizadas com a batida de uma música.','Sentir o tempo da edição e a relação som-imagem.',array['Grave 20 clipes curtos do seu dia.','Escolha uma música com batida clara.','Marque as batidas na timeline e corte exatamente nelas.','Exporte em 9:16 para redes.']::text[],null,array['ritmo-repeticao','cartaz-festival-som']::text[],array['ritmo','edição']::text[]) on conflict (slug) do update set title=excluded.title, category=excluded.category, kind=excluded.kind, difficulty=excluded.difficulty, minutes=excluded.minutes, xp=excluded.xp, summary=excluded.summary, objective=excluded.objective, instructions=excluded.instructions, steps=excluded.steps, reference_slugs=excluded.reference_slugs, tags=excluded.tags;
insert into public.challenges (slug,title,category,kind,difficulty,minutes,xp,summary,objective,instructions,steps,reference_slugs,tags) values ('still-com-o-que-tem','Still com o que tem em casa','direcao-de-arte','diario','intermediario',45,90,'Monte um still life com 3 objetos e um fundo de cor chapada.','Tomar decisões de cor, forma e luz como diretor de arte.',array['Escolha um papel ou tecido colorido como fundo.','Selecione 3 objetos com uma regra (mesma cor, mesma forma ou contraste).','Use luz dura (sol ou lanterna) para sombras marcadas.','Escreva o ''moodboard em 3 palavras'' da cena.']::text[],null,array['still-life-cromatico','set-monocromatico']::text[],array['still','produção']::text[]) on conflict (slug) do update set title=excluded.title, category=excluded.category, kind=excluded.kind, difficulty=excluded.difficulty, minutes=excluded.minutes, xp=excluded.xp, summary=excluded.summary, objective=excluded.objective, instructions=excluded.instructions, steps=excluded.steps, reference_slugs=excluded.reference_slugs, tags=excluded.tags;
insert into public.challenges (slug,title,category,kind,difficulty,minutes,xp,summary,objective,instructions,steps,reference_slugs,tags) values ('moodboard-de-um-sentimento','Moodboard de um sentimento','direcao-de-arte','diario','iniciante',30,60,'Monte um painel visual que represente ''saudade'' sem usar nenhuma pessoa.','Traduzir conceitos abstratos em linguagem visual.',array['Reúna 9 imagens (suas ou da biblioteca de referências).','Inclua uma paleta de 4 cores e uma textura.','Escolha uma fonte que ''soe'' como o sentimento.','Escreva 2 linhas explicando as escolhas.']::text[],null,array['paleta-terra-quente','luz-de-janela']::text[],array['moodboard','conceito']::text[]) on conflict (slug) do update set title=excluded.title, category=excluded.category, kind=excluded.kind, difficulty=excluded.difficulty, minutes=excluded.minutes, xp=excluded.xp, summary=excluded.summary, objective=excluded.objective, instructions=excluded.instructions, steps=excluded.steps, reference_slugs=excluded.reference_slugs, tags=excluded.tags;
insert into public.challenges (slug,title,category,kind,difficulty,minutes,xp,summary,objective,instructions,steps,reference_slugs,tags) values ('carrossel-que-ensina','Carrossel que ensina','social','diario','intermediario',45,90,'Crie um carrossel de 5 slides ensinando algo que você sabe fazer.','Unir copy, hierarquia e sequência narrativa.',array['Slide 1: gancho em até 7 palavras.','Slides 2–4: um passo por slide, com um elemento visual consistente.','Slide 5: resumo + chamada para ação.','Mantenha a mesma grade em todos os slides.']::text[],null,array['campanha-pergunta','cartaz-suico']::text[],array['carrossel','copy']::text[]) on conflict (slug) do update set title=excluded.title, category=excluded.category, kind=excluded.kind, difficulty=excluded.difficulty, minutes=excluded.minutes, xp=excluded.xp, summary=excluded.summary, objective=excluded.objective, instructions=excluded.instructions, steps=excluded.steps, reference_slugs=excluded.reference_slugs, tags=excluded.tags;
insert into public.challenges (slug,title,category,kind,difficulty,minutes,xp,summary,objective,instructions,steps,reference_slugs,tags) values ('feed-de-nove','Feed de 9 quadros','social','diario','avancado',60,120,'Planeje 9 posts que, juntos, formem uma imagem ou padrão no grid do perfil.','Pensar em sistema visual e consistência de marca.',array['Defina um tema e uma paleta de no máximo 4 cores.','Desenhe o grid 3×3 completo antes de criar os posts.','Garanta que cada post funcione sozinho e no conjunto.']::text[],null,array['identidade-modular','ritmo-repeticao']::text[],array['grid','sistema']::text[]) on conflict (slug) do update set title=excluded.title, category=excluded.category, kind=excluded.kind, difficulty=excluded.difficulty, minutes=excluded.minutes, xp=excluded.xp, summary=excluded.summary, objective=excluded.objective, instructions=excluded.instructions, steps=excluded.steps, reference_slugs=excluded.reference_slugs, tags=excluded.tags;
insert into public.challenges (slug,title,category,kind,difficulty,minutes,xp,summary,objective,instructions,steps,reference_slugs,tags) values ('palavra-que-age','A palavra que age','tipografia','diario','iniciante',20,50,'Escreva palavras de modo que a forma represente o significado (ex.: ''queda'').','Explorar tipografia expressiva.',array['Escolha 5 verbos: cair, esticar, quebrar, flutuar, apertar.','Componha cada palavra para que ela ''faça'' o que diz.','Use apenas uma família tipográfica.']::text[],null,array['cartaz-tipografico-brutal','serif-em-movimento']::text[],array['expressiva','lettering']::text[]) on conflict (slug) do update set title=excluded.title, category=excluded.category, kind=excluded.kind, difficulty=excluded.difficulty, minutes=excluded.minutes, xp=excluded.xp, summary=excluded.summary, objective=excluded.objective, instructions=excluded.instructions, steps=excluded.steps, reference_slugs=excluded.reference_slugs, tags=excluded.tags;
insert into public.challenges (slug,title,category,kind,difficulty,minutes,xp,summary,objective,instructions,steps,reference_slugs,tags) values ('par-perfeito','O par perfeito','tipografia','diario','intermediario',35,70,'Crie 3 combinações tipográficas (título + texto) para 3 marcas diferentes.','Aprender contraste e harmonia entre famílias.',array['Marcas: uma livraria, um estúdio de tatuagem, uma fintech.','Para cada uma, combine uma fonte de título com uma de texto.','Aplique em uma mini peça com título, subtítulo e parágrafo.']::text[],null,array['serif-em-movimento','grotesca-condensada']::text[],array['pairing','hierarquia']::text[]) on conflict (slug) do update set title=excluded.title, category=excluded.category, kind=excluded.kind, difficulty=excluded.difficulty, minutes=excluded.minutes, xp=excluded.xp, summary=excluded.summary, objective=excluded.objective, instructions=excluded.instructions, steps=excluded.steps, reference_slugs=excluded.reference_slugs, tags=excluded.tags;
insert into public.challenges (slug,title,category,kind,difficulty,minutes,xp,summary,objective,instructions,steps,reference_slugs,tags) values ('trinta-circulos','30 círculos','livre','diario','iniciante',15,40,'Desenhe 30 círculos e transforme cada um em algo diferente em 10 minutos.','Aquecer a fluência criativa (quantidade antes de qualidade).',array['Desenhe uma grade 5×6 de círculos em uma folha.','Cronometre 10 minutos.','Transforme o máximo de círculos em objetos, rostos, logos, planetas…','Conte quantos conseguiu e anote as ideias mais estranhas.']::text[],null,array['ritmo-repeticao','espaco-negativo']::text[],array['aquecimento','fluência']::text[]) on conflict (slug) do update set title=excluded.title, category=excluded.category, kind=excluded.kind, difficulty=excluded.difficulty, minutes=excluded.minutes, xp=excluded.xp, summary=excluded.summary, objective=excluded.objective, instructions=excluded.instructions, steps=excluded.steps, reference_slugs=excluded.reference_slugs, tags=excluded.tags;
insert into public.challenges (slug,title,category,kind,difficulty,minutes,xp,summary,objective,instructions,steps,reference_slugs,tags) values ('e-se','E se…?','livre','diario','intermediario',30,70,'Escreva 10 perguntas ''e se'' sobre um objeto comum e visualize a mais absurda.','Praticar pensamento divergente e reenquadramento.',array['Escolha um objeto: guarda-chuva, cadeira ou garrafa.','Escreva 10 perguntas ''E se ele…?''.','Escolha a mais absurda e transforme em imagem (foto, desenho ou colagem).']::text[],null,array['campanha-objeto-unico','still-life-cromatico']::text[],array['divergente','absurdo']::text[]) on conflict (slug) do update set title=excluded.title, category=excluded.category, kind=excluded.kind, difficulty=excluded.difficulty, minutes=excluded.minutes, xp=excluded.xp, summary=excluded.summary, objective=excluded.objective, instructions=excluded.instructions, steps=excluded.steps, reference_slugs=excluded.reference_slugs, tags=excluded.tags;
insert into public.challenges (slug,title,category,kind,difficulty,minutes,xp,summary,objective,instructions,steps,reference_slugs,tags) values ('remix-de-referencia','Remix de referência','livre','diario','avancado',60,110,'Escolha uma referência da biblioteca e recrie-a em outra linguagem.','Aprender a se inspirar sem copiar: extrair o princípio, não a forma.',array['Escolha uma referência do Laboratório.','Escreva o princípio dela em uma frase.','Aplique o mesmo princípio em outra mídia (cartaz → foto, foto → vídeo…).','Mostre a referência e o seu remix lado a lado.']::text[],null,array['espaco-negativo','cartaz-festival-som','set-monocromatico']::text[],array['remix','princípio']::text[]) on conflict (slug) do update set title=excluded.title, category=excluded.category, kind=excluded.kind, difficulty=excluded.difficulty, minutes=excluded.minutes, xp=excluded.xp, summary=excluded.summary, objective=excluded.objective, instructions=excluded.instructions, steps=excluded.steps, reference_slugs=excluded.reference_slugs, tags=excluded.tags;
insert into public.challenges (slug,title,category,kind,difficulty,minutes,xp,summary,objective,instructions,steps,reference_slugs,tags) values ('semana-da-cor','Semana da cor','direcao-de-arte','especial-7','intermediario',30,350,'7 dias, 7 cores: produza uma imagem por dia guiada por uma única cor.','Desenvolver sensibilidade cromática e consistência diária.',array['Siga uma cor por dia, na ordem abaixo.','Cada imagem pode ser foto, colagem ou design.','Ao final, monte um painel com as 7 imagens.']::text[],array['Dia 1 — Vermelho: urgência','Dia 2 — Laranja: energia','Dia 3 — Amarelo: luz','Dia 4 — Verde: crescimento','Dia 5 — Azul: silêncio','Dia 6 — Violeta: mistério','Dia 7 — Preto: síntese']::text[],array['retrato-cor-unica','set-monocromatico','paleta-noite-neon']::text[],array['cor','constância']::text[]) on conflict (slug) do update set title=excluded.title, category=excluded.category, kind=excluded.kind, difficulty=excluded.difficulty, minutes=excluded.minutes, xp=excluded.xp, summary=excluded.summary, objective=excluded.objective, instructions=excluded.instructions, steps=excluded.steps, reference_slugs=excluded.reference_slugs, tags=excluded.tags;
insert into public.challenges (slug,title,category,kind,difficulty,minutes,xp,summary,objective,instructions,steps,reference_slugs,tags) values ('sete-dias-de-tipo','7 dias de tipo','tipografia','especial-7','iniciante',20,300,'Uma semana explorando letras: do lettering à composição editorial.','Construir repertório tipográfico em pequenas doses.',array['Complete uma etapa por dia.','Poste ou salve cada resultado no portfólio.']::text[],array['Dia 1 — Fotografe 10 letras encontradas na rua','Dia 2 — Desenhe seu nome em 3 estilos','Dia 3 — Crie um alfabeto de 5 letras com formas geométricas','Dia 4 — Componha um poema curto só com tipografia','Dia 5 — Faça um par tipográfico para uma marca','Dia 6 — Monte uma página de revista','Dia 7 — Cartaz final usando tudo que aprendeu']::text[],array['grotesca-condensada','serif-em-movimento','cartaz-tipografico-brutal']::text[],array['tipografia','repertório']::text[]) on conflict (slug) do update set title=excluded.title, category=excluded.category, kind=excluded.kind, difficulty=excluded.difficulty, minutes=excluded.minutes, xp=excluded.xp, summary=excluded.summary, objective=excluded.objective, instructions=excluded.instructions, steps=excluded.steps, reference_slugs=excluded.reference_slugs, tags=excluded.tags;
insert into public.challenges (slug,title,category,kind,difficulty,minutes,xp,summary,objective,instructions,steps,reference_slugs,tags) values ('olhar-de-rua-7','Olhar de rua','fotografia','especial-7','avancado',45,400,'Uma semana de fotografia de rua com uma regra nova a cada dia.','Ganhar coragem, timing e leitura de cena.',array['Saia todos os dias por pelo menos 30 minutos.','Selecione a melhor foto de cada dia.']::text[],array['Dia 1 — Só sombras','Dia 2 — Só reflexos','Dia 3 — Uma cor dominante','Dia 4 — Pessoas de costas','Dia 5 — Camadas (frente, meio, fundo)','Dia 6 — Movimento com velocidade baixa','Dia 7 — Ensaio de 5 fotos com um tema']::text[],array['sombras-urbanas','geometria-de-rua']::text[],array['rua','timing']::text[]) on conflict (slug) do update set title=excluded.title, category=excluded.category, kind=excluded.kind, difficulty=excluded.difficulty, minutes=excluded.minutes, xp=excluded.xp, summary=excluded.summary, objective=excluded.objective, instructions=excluded.instructions, steps=excluded.steps, reference_slugs=excluded.reference_slugs, tags=excluded.tags;
insert into public.challenges (slug,title,category,kind,difficulty,minutes,xp,summary,objective,instructions,steps,reference_slugs,tags) values ('trinta-dias-criando','30 dias criando','livre','especial-30','intermediario',20,1500,'O grande desafio: criar algo todos os dias durante 30 dias, em 4 fases.','Transformar criatividade em hábito.',array['Reserve 20 minutos por dia no mesmo horário.','Siga as fases semanais abaixo.','Registre cada dia no portfólio — a constância vale mais que a perfeição.']::text[],array['Semana 1 — Aquecimento: rascunhos rápidos e listas de ideias','Semana 2 — Limitação: uma regra diferente por dia','Semana 3 — Remix: reinterprete uma referência por dia','Semana 4 — Autoria: uma série pessoal de 7 peças','Dias 29–30 — Curadoria: escolha as 9 melhores e apresente']::text[],array['ritmo-repeticao','campanha-objeto-unico','espaco-negativo']::text[],array['hábito','constância']::text[]) on conflict (slug) do update set title=excluded.title, category=excluded.category, kind=excluded.kind, difficulty=excluded.difficulty, minutes=excluded.minutes, xp=excluded.xp, summary=excluded.summary, objective=excluded.objective, instructions=excluded.instructions, steps=excluded.steps, reference_slugs=excluded.reference_slugs, tags=excluded.tags;
insert into public.challenges (slug,title,category,kind,difficulty,minutes,xp,summary,objective,instructions,steps,reference_slugs,tags) values ('marca-do-zero-30','Uma marca do zero','design','especial-30','avancado',40,1800,'Em 30 dias, construa uma identidade visual completa para uma marca fictícia.','Viver o processo real de branding: pesquisa, conceito, sistema e aplicações.',array['Invente um negócio com nome e propósito.','Avance uma etapa por bloco de dias.','Documente o processo no portfólio.']::text[],array['Dias 1–5 — Pesquisa, público e concorrentes','Dias 6–10 — Conceito e palavras-chave','Dias 11–17 — Logo e variações','Dias 18–22 — Cor, tipografia e grafismos','Dias 23–27 — Aplicações (social, embalagem, sinalização)','Dias 28–30 — Manual da marca e apresentação']::text[],array['identidade-modular','marca-cafe-lento','paleta-concreto-limao']::text[],array['branding','processo']::text[]) on conflict (slug) do update set title=excluded.title, category=excluded.category, kind=excluded.kind, difficulty=excluded.difficulty, minutes=excluded.minutes, xp=excluded.xp, summary=excluded.summary, objective=excluded.objective, instructions=excluded.instructions, steps=excluded.steps, reference_slugs=excluded.reference_slugs, tags=excluded.tags;
insert into public.creative_references (slug,title,kind,author,year,description,insight,palette,tags,seed,ratio) values ('luz-de-janela','Luz de janela, 16h','fotografia','Estudo CRIATIVA LAB',2025,'Retrato com uma única fonte de luz lateral e sombra profunda no lado oposto.','Uma janela é um softbox gratuito. Afaste o modelo da parede para a sombra cair no vazio.',array['#0d0d0d','#3b2f25','#c99a6b','#f1e3cf']::text[],array['luz natural','retrato','chiaroscuro']::text[],11,'portrait') on conflict (slug) do update set title=excluded.title, kind=excluded.kind, author=excluded.author, year=excluded.year, description=excluded.description, insight=excluded.insight, palette=excluded.palette, tags=excluded.tags, seed=excluded.seed, ratio=excluded.ratio;
