insert into public.courses (slug,title,subtitle,category,level,color,position) values ('composicao-fotografica','Composição fotográfica','Onde colocar as coisas — e por quê.','fotografia','iniciante','#d4ff3a',0) on conflict (slug) do update set title=excluded.title, subtitle=excluded.subtitle, category=excluded.category, level=excluded.level, color=excluded.color, position=excluded.position;
insert into public.lessons (course_slug,slug,title,minutes,body,exercise,position) values ('composicao-fotografica','o-quadro-e-uma-decisao','O quadro é uma decisão',6,array['Toda foto começa pelo que fica de fora. Enquadrar é editar o mundo antes do clique.','Antes de fotografar, pergunte: qual é o assunto? O que distrai dele? Dê um passo à frente ou mude o ângulo até que só reste o essencial.']::text[],'Fotografe o mesmo objeto 5 vezes, removendo um elemento distrativo a cada foto.',0) on conflict (course_slug,slug) do update set title=excluded.title, minutes=excluded.minutes, body=excluded.body, exercise=excluded.exercise, position=excluded.position;
insert into public.lessons (course_slug,slug,title,minutes,body,exercise,position) values ('composicao-fotografica','tercos-linhas-e-diagonais','Terços, linhas e diagonais',8,array['A regra dos terços divide o quadro em 9 partes; os pontos de interseção atraem o olhar.','Linhas guiam: estradas, corrimãos e sombras levam o olho até o assunto. Diagonais criam movimento; horizontais, calma.']::text[],'Faça 3 fotos: uma com linha guia, uma com diagonal forte e uma com o assunto num ponto de terço.',1) on conflict (course_slug,slug) do update set title=excluded.title, minutes=excluded.minutes, body=excluded.body, exercise=excluded.exercise, position=excluded.position;
insert into public.lessons (course_slug,slug,title,minutes,body,exercise,position) values ('composicao-fotografica','espaco-negativo-e-escala','Espaço negativo e escala',7,array['O vazio não é desperdício: ele dá respiro e importância ao assunto.','Um assunto pequeno num grande espaço comunica solidão, liberdade ou grandiosidade.']::text[],'Crie uma foto em que o assunto ocupe menos de 10% do quadro.',2) on conflict (course_slug,slug) do update set title=excluded.title, minutes=excluded.minutes, body=excluded.body, exercise=excluded.exercise, position=excluded.position;
insert into public.courses (slug,title,subtitle,category,level,color,position) values ('iluminacao','Iluminação','Luz é o verdadeiro assunto de toda imagem.','fotografia','intermediario','#ffd23f',1) on conflict (slug) do update set title=excluded.title, subtitle=excluded.subtitle, category=excluded.category, level=excluded.level, color=excluded.color, position=excluded.position;
insert into public.lessons (course_slug,slug,title,minutes,body,exercise,position) values ('iluminacao','dura-ou-suave','Luz dura ou suave',7,array['Quanto menor a fonte em relação ao assunto, mais dura a luz e mais marcada a sombra.','Aproxime uma janela grande para suavizar; use o sol do meio-dia para drama gráfico.']::text[],'Fotografe um rosto com luz dura e com luz suave e compare a emoção.',0) on conflict (course_slug,slug) do update set title=excluded.title, minutes=excluded.minutes, body=excluded.body, exercise=excluded.exercise, position=excluded.position;
insert into public.lessons (course_slug,slug,title,minutes,body,exercise,position) values ('iluminacao','direcao-da-luz','A direção da luz',6,array['Luz frontal achata; lateral revela textura; contraluz cria silhueta e halo.','Mudar a posição do assunto em relação à luz é mais barato que comprar equipamento.']::text[],'Gire ao redor de um objeto e fotografe a cada 45°, mantendo a luz fixa.',1) on conflict (course_slug,slug) do update set title=excluded.title, minutes=excluded.minutes, body=excluded.body, exercise=excluded.exercise, position=excluded.position;
insert into public.lessons (course_slug,slug,title,minutes,body,exercise,position) values ('iluminacao','cor-da-luz','A cor da luz',6,array['Luz quente (amanhecer, lâmpadas incandescentes) aconchega; fria (sombra, LED) distancia.','Misturar temperaturas de cor de propósito cria tensão cinematográfica.']::text[],'Crie uma cena com uma fonte quente e uma fria ao mesmo tempo.',2) on conflict (course_slug,slug) do update set title=excluded.title, minutes=excluded.minutes, body=excluded.body, exercise=excluded.exercise, position=excluded.position;
insert into public.courses (slug,title,subtitle,category,level,color,position) values ('teoria-das-cores','Teoria das cores','Cor é emoção com coordenadas.','design','iniciante','#ff5c39',2) on conflict (slug) do update set title=excluded.title, subtitle=excluded.subtitle, category=excluded.category, level=excluded.level, color=excluded.color, position=excluded.position;
insert into public.lessons (course_slug,slug,title,minutes,body,exercise,position) values ('teoria-das-cores','matiz-saturacao-luminosidade','Matiz, saturação e luminosidade',6,array['Toda cor tem três dimensões. Mexer na luminosidade muda a hierarquia; na saturação, a energia.','Teste sua paleta em escala de cinza: se tudo vira o mesmo cinza, falta contraste.']::text[],'Crie uma paleta de 5 cores e verifique o contraste em preto e branco.',0) on conflict (course_slug,slug) do update set title=excluded.title, minutes=excluded.minutes, body=excluded.body, exercise=excluded.exercise, position=excluded.position;
insert into public.lessons (course_slug,slug,title,minutes,body,exercise,position) values ('teoria-das-cores','harmonias','Harmonias cromáticas',8,array['Análogas acalmam, complementares vibram, triádicas equilibram.','A regra 60-30-10 ajuda: 60% cor dominante, 30% secundária, 10% acento.']::text[],'Aplique a regra 60-30-10 em um post usando uma paleta da biblioteca.',1) on conflict (course_slug,slug) do update set title=excluded.title, minutes=excluded.minutes, body=excluded.body, exercise=excluded.exercise, position=excluded.position;
insert into public.lessons (course_slug,slug,title,minutes,body,exercise,position) values ('teoria-das-cores','cor-e-significado','Cor e significado',6,array['Significados de cor são culturais e contextuais. Vermelho é perigo, paixão ou promoção dependendo do entorno.','Defina a emoção primeiro; escolha a cor depois.']::text[],'Escolha 3 emoções e crie uma paleta para cada uma.',2) on conflict (course_slug,slug) do update set title=excluded.title, minutes=excluded.minutes, body=excluded.body, exercise=excluded.exercise, position=excluded.position;
