insert into public.lessons (course_slug,slug,title,minutes,body,exercise,position) values ('tipografia','anatomia-da-letra','Anatomia da letra',6,array['Serifa, haste, altura-x, contraste: conhecer as partes ajuda a escolher com intenção.','Fontes com altura-x grande leem melhor em tamanhos pequenos.']::text[],'Compare 3 fontes escrevendo a mesma frase e anote as diferenças de altura-x e contraste.',0) on conflict (course_slug,slug) do update set title=excluded.title, minutes=excluded.minutes, body=excluded.body, exercise=excluded.exercise, position=excluded.position;
insert into public.lessons (course_slug,slug,title,minutes,body,exercise,position) values ('tipografia','hierarquia','Hierarquia tipográfica',7,array['Tamanho, peso, cor e espaço definem o que é lido primeiro.','Use no máximo 3 níveis de hierarquia por peça. Mais do que isso vira ruído.']::text[],'Diagrame um anúncio com título, subtítulo e texto usando só uma família.',1) on conflict (course_slug,slug) do update set title=excluded.title, minutes=excluded.minutes, body=excluded.body, exercise=excluded.exercise, position=excluded.position;
insert into public.lessons (course_slug,slug,title,minutes,body,exercise,position) values ('tipografia','combinacoes','Combinando fontes',6,array['Combine por contraste (serifa + sem serifa) ou por parentesco (mesma família, pesos diferentes).','Evite duas fontes ''parecidas mas diferentes'' — isso parece erro.']::text[],'Crie 2 pares tipográficos: um por contraste e um por parentesco.',2) on conflict (course_slug,slug) do update set title=excluded.title, minutes=excluded.minutes, body=excluded.body, exercise=excluded.exercise, position=excluded.position;
