insert into public.lessons (course_slug,slug,title,minutes,body,exercise,position) values ('design-editorial','o-grid','O grid invisível',8,array['Grids dão coerência entre páginas e liberdade para quebrar com intenção.','Comece com 6 ou 12 colunas e margens generosas.']::text[],'Desenhe um grid de 6 colunas e diagrame uma página com imagem e texto.',0) on conflict (course_slug,slug) do update set title=excluded.title, minutes=excluded.minutes, body=excluded.body, exercise=excluded.exercise, position=excluded.position;
insert into public.lessons (course_slug,slug,title,minutes,body,exercise,position) values ('design-editorial','ritmo-de-paginas','Ritmo entre páginas',6,array['Alternar páginas densas e páginas de respiro mantém o leitor engajado.','Pense numa revista como música: refrões, pausas e clímax.']::text[],'Planeje o espelho de uma revista de 8 páginas marcando ritmo denso/leve.',1) on conflict (course_slug,slug) do update set title=excluded.title, minutes=excluded.minutes, body=excluded.body, exercise=excluded.exercise, position=excluded.position;
