insert into public.lessons (course_slug,slug,title,minutes,body,exercise,position) values ('storytelling-visual','conflito','Toda história tem conflito',7,array['Sem tensão não há história. Mesmo uma foto única pode sugerir ''antes'' e ''depois''.','Pergunte: o que o espectador quer saber que a imagem não mostra?']::text[],'Crie uma imagem que faça o espectador perguntar ''o que aconteceu?''.',0) on conflict (course_slug,slug) do update set title=excluded.title, minutes=excluded.minutes, body=excluded.body, exercise=excluded.exercise, position=excluded.position;
insert into public.lessons (course_slug,slug,title,minutes,body,exercise,position) values ('storytelling-visual','sequencia','Sequência e série',6,array['Três imagens já formam uma narrativa: situação, mudança, consequência.','Mantenha uma constante (cor, enquadramento, personagem) para conectar a série.']::text[],'Conte uma história em 3 fotos mantendo o mesmo enquadramento.',1) on conflict (course_slug,slug) do update set title=excluded.title, minutes=excluded.minutes, body=excluded.body, exercise=excluded.exercise, position=excluded.position;
insert into public.courses (slug,title,subtitle,category,level,color,position) values ('edicao-de-fotografia','Edição de fotografia','Do arquivo bruto à imagem final.','fotografia','intermediario','#5cffc8',6) on conflict (slug) do update set title=excluded.title, subtitle=excluded.subtitle, category=excluded.category, level=excluded.level, color=excluded.color, position=excluded.position;
insert into public.lessons (course_slug,slug,title,minutes,body,exercise,position) values ('edicao-de-fotografia','fluxo-basico','Fluxo básico de edição',8,array['Ordem recomendada: corte e alinhamento → exposição → balanço de branco → contraste → cor → detalhes.','Edite pela emoção, não pelo filtro da moda.']::text[],'Edite uma foto seguindo a ordem e salve um ''antes e depois''.',0) on conflict (course_slug,slug) do update set title=excluded.title, minutes=excluded.minutes, body=excluded.body, exercise=excluded.exercise, position=excluded.position;
