insert into public.lessons (course_slug,slug,title,minutes,body,exercise,position) values ('direcao-de-arte','conceito-antes-da-forma','Conceito antes da forma',8,array['O diretor de arte traduz uma ideia em decisões visuais: cor, luz, cenário, figurino, tipografia.','Escreva o conceito em uma frase. Se não cabe numa frase, ainda não é um conceito.']::text[],'Escreva o conceito de uma campanha em uma frase e liste 5 decisões visuais derivadas dela.',0) on conflict (course_slug,slug) do update set title=excluded.title, minutes=excluded.minutes, body=excluded.body, exercise=excluded.exercise, position=excluded.position;
